  ('a1000000-0000-4000-8000-000000000001', 'savar-greens', 'সাভার গ্রিনস খামার', 'Savar Greens Farm', 'vegetables', 'মোঃ রহিম উদ্দিন', '01711000001', '/images/cat/vegetables.jpg', 'তিন প্রজন্ম ধরে সাভারে শাক চাষ করছেন রহিম ভাই। ১২ বিঘা জমিতে গোবর সার আর জৈব বালাইনাশ ব্যবহার করেন। প্রতিদিন ভোর ৫টায় সবজি তোলা হয়।', 'ঢাকা', 'ঢাকা', 'সাভার', 'বাগবাড়ি, সাভার, ঢাকা ১৩৪০', 23.8384, 90.2639, '[[90.2618,23.8372],[90.2658,23.8374],[90.2661,23.8398],[90.262,23.8396],[90.2618,23.8372]]'::jsonb, '[{"month":"অগ্রহায়ণ","crops":["পালং শাক","লাল শাক","মুলা"]},{"month":"পৌষ","crops":["ফুলকপি","বাঁধাকপি","গাজর"]},{"month":"মাঘ","crops":["টমেটো","ঢেঁড়স"]},{"month":"ফাল্গুন","crops":["করলা","পটল","বেগুন"]}]'::jsonb, 'সাভারের ১২ বিঘার জৈব সবজি খামার। প্রতিটি সবজি তোলার পর হাতে বাছাই করে বাঁশের ঝুড়িতে প্যাক করা হয়। কোনো কৃত্রিম রিপেনিং বা কীটনাশক ব্যবহার করা হয় না।', '২০১১ সালে ২ বিঘা জমি দিয়ে শুরু। এখন ৩৫ জন কৃষক পরিবার একসাথে কাজ করেন। খামারের পাশেই ছোট প্যাকিং শেড যেখানে প্রতিদিন সকালে সবজি ধোয়া ও বাছাই হয়।', '/images/cat/vegetables.jpg', array['/images/cat/vegetables.jpg','/images/hero/farm.jpg']::text[], '{"note_bn":"প্রতিদিন গড়ে ৩২০ কেজি সবজি সংগ্রহ","updated_at":"2026-11-21T20:03:29.973Z"}'::jsonb, 2011, array['জৈব সার সনদ','বারবি রেসিডিউ টেস্ট ফ্রি']::text[], true, true, 1),
  ('a1000000-0000-4000-8000-000000000002', 'tangail-dairy', 'টাঙ্গাইল ডেইরি ফার্ম', 'Tangail Dairy Farm', 'dairy', 'আব্দুল করিম মিয়া', '01711000002', '/images/cat/dairy.jpg', '৪০টি দেশি গাভী নিয়ে ডেইরি চালান করিম মিয়া। কোনো বুস্টার বা হরমোন ব্যবহার করেন না। প্রতিদিন সকালের দুধ দুপুরের মধ্যে কোল্ড চেইনে পৌঁছে যায়।', 'ঢাকা', 'টাঙ্গাইল', 'সদর', 'কলিয়া, টাঙ্গাইল সদর, টাঙ্গাইল ১৯০০', 24.2513, 89.9167, '[[89.9142,24.2498],[89.9192,24.2501],[89.9195,24.2529],[89.9145,24.2526],[89.9142,24.2498]]'::jsonb, '[{"month":"সারা বছর","crops":["গরুর দুধ","ঘি","ছানা","দই"]}]'::jsonb, '৪০টি দেশি ও শাহীওয়াল সংকর গাভীর ডেইরি। প্রতিটি গাভীর দুধ আলাদাভাবে পরীক্ষা করা হয় — ফ্যাট, ঘনত্ব ও অ্যান্টিবায়োটিক রেসিডিউ।', '২০১৫ সালে ৬টি গাভী দিয়ে শুরু। এখন প্রতিদিন ৪২০ লিটার দুধ, যার সবটাই বিশ্বাস এগ্রোর কোল্ড চেইনে যায়। গোয়ালঘরে ২৪ ঘণ্টা CCTV — গ্রাহক নিজেই দেখতে পারেন গাভী কীভাবে খেতে ও দোহন হচ্ছে।', '/images/cat/dairy.jpg', array['/images/cat/dairy.jpg','/images/cat/dairy.jpg']::text[], '{"cows":40,"litres_today":418,"litres_week":2916,"sold_today":402,"updated_at":"2026-11-21T20:03:29.975Z","note_bn":"ভোর ৪:৩০ ও বিকাল ৪:০০ — দিনে দুইবার দোহন"}'::jsonb, 2015, array['লাইভস্টক ডিপার্টমেন্ট নিবন্ধিত','অ্যান্টিবায়োটিক ফ্রি']::text[], true, true, 2),
  ('a1000000-0000-4000-8000-000000000003', 'gazipur-poultry', 'গাজীপুর পোল্ট্রি খামার', 'Gazipur Poultry Farm', 'poultry', 'সালমা বেগম', '01711000003', '/images/cat/eggs.jpg', 'নারী উদ্যোক্তা সালমা বেগমের নেতৃত্বে ৮টি শেডে দেশি মুরগি পালন হয়। মুক্ত চারণে বেড়ে ওঠা মুরগির ডিম প্রতিদিন সকালে সংগ্রহ করা হয়।', 'ঢাকা', 'গাজীপুর', 'শ্রীপুর', 'বরমী, শ্রীপুর, গাজীপুর ১৭৪৪', 24.1667, 90.4167, '[[90.4142,24.1652],[90.4192,24.1655],[90.4195,24.1682],[90.4145,24.1679],[90.4142,24.1652]]'::jsonb, '[{"month":"সারা বছর","crops":["দেশি ডিম","হাঁসের ডিম","দেশি মুরগি"]}]'::jsonb, '৮টি শেডে প্রায় ৩,২০০ দেশি মুরগি। মুক্ত চারণে ঘাস, পোকা ও ভুট্টা খেয়ে বেড়ে ওঠে — তাই কুসুম গাঢ় কমলা।', 'সালমা বেগম ২০১৮ সালে ২০০ মুরগি দিয়ে শুরু করেন। এখন ২২ জন মহিলা কর্মী কাজ করেন। প্রতিটি ডিম সংগ্রহ করে হাতে বাছাই করা হয়, ফাটা বা নোংরা ডিম কখনো প্যাক হয় না।', '/images/cat/eggs.jpg', array['/images/cat/eggs.jpg']::text[], '{"note_bn":"প্রতিদিন গড়ে ২,৮০০ ডিম সংগ্রহ","updated_at":"2026-11-21T20:03:29.975Z"}'::jsonb, 2018, array['মুক্ত চারণ সনদ','ডিম কোয়ালিটি গ্রেড এ']::text[], true, true, 3),
  ('a1000000-0000-4000-8000-000000000004', 'khulna-shrimp', 'খুলনা বাগদা চিংড়ি ঘের', 'Khulna Bagda Shrimp Gher', 'fish', 'মোঃ জাহাঙ্গীর হোসেন', '01711000004', '/images/cat/fish.jpg', 'খুলনার লবণাক্ত পানির ঘেরে বাগদা চিংড়ি চাষ করেন জাহাঙ্গীর। প্রাকৃতিক খাদ্য ছাড়া কোনো ফিড বা কেমিক্যাল ব্যবহার নেই।', 'খুলনা', 'খুলনা', 'বটিয়াঘাটা', 'সুরখালী, বটিয়াঘাটা, খুলনা ৯২৬০', 22.7, 89.55, '[[89.5472,22.6982],[89.5532,22.6986],[89.5536,22.7022],[89.5476,22.7018],[89.5472,22.6982]]'::jsonb, '[{"month":"চৈত্র","crops":["বাগদা পোনা ছাড়া"]},{"month":"ভাদ্র","crops":["বাগদা চিংড়ি সংগ্রহ","গলদা"]}]'::jsonb, '৬ একরের ঘের, লবণাক্ত পানির প্রাকৃতিক প্রবাহ। ইলিশ-চিংড়ি বিক্রি হয় সকালে ধরার পর পরই — আইস প্যাকে ২ ঘণ্টার মধ্যে।', 'তিন প্রজন্মের জেলে পরিবার। এখন ঘেরে CCTV বসানো হয়েছে যাতে গ্রাহক দেখতে পারেন যে পানির মান ও চিংড়ি কেমন আছে, এবং জাল তোলার সময় নিজে দেখে নিতে পারেন।', '/images/cat/fish.jpg', array['/images/cat/fish.jpg']::text[], '{"note_bn":"প্রতিদিন গড়ে ১৫ কেজি চিংড়ি ও ৪০ কেজি মাছ","updated_at":"2026-11-21T20:03:29.975Z"}'::jsonb, 2009, array['রপ্তানি মান যাচাই','কোনো ফিড নেই']::text[], true, true, 4),
  ('a1000000-0000-4000-8000-000000000005', 'rajshahi-mango', 'রাজশাহী আম বাগান', 'Rajshahi Mango Orchard', 'fruits', 'ফাতেমা বেগম', '01711000005', '/images/cat/fruits.jpg', 'রাজশাহীর ২২ বিঘার আম বাগান, সাতটি জাত। কার্বাইড ছাড়া প্রাকৃতিকভাবে পাকানো হয়।', 'রাজশাহী', 'রাজশাহী', 'চারঘাট', 'পবা, রাজশাহী ৬২১০', 24.3745, 88.6042, '[[88.6012,24.3728],[88.6078,24.3732],[88.6082,24.3766],[88.6016,24.3762],[88.6012,24.3728]]'::jsonb, '[{"month":"বৈশাখ","crops":["গোপালভোগ","হিমসাগর"]},{"month":"জ্যৈষ্ঠ","crops":["ল্যাংড়া","ক্ষীরশাপাতি"]},{"month":"আষাঢ়","crops":["আম্রপালি","ফজলি"]}]'::jsonb, '২২ বিঘার বাগানে ৩৫০টির বেশি আম গাছ। বাঁশের ঝুড়িতে খড় বিছিয়ে প্যাক করা হয়, বিছানায় রেখে ২–৩ দিনে নিজে থেকে পাকে।', 'ফাতেমা বেগম ৩৫ জন কৃষক পরিবারের সমবায় চালান। আলুর জন্য বিখ্যাত হলেও এখন আমই প্রধান আয়ের উৎস — সারা বছর সাতটি জাত ধাপে ধাপে সংগ্রহ করা হয়।', '/images/cat/fruits.jpg', array['/images/cat/fruits.jpg','/images/cat/honey.jpg']::text[], '{"note_bn":"মৌসুমে প্রতিদিন ১.২ টন আম সংগ্রহ","updated_at":"2026-11-21T20:03:29.975Z"}'::jsonb, 2004, array['সমবায় নিবন্ধিত','কার্বাইড ফ্রি']::text[], true, true, 5)
